#define CHECK(x) do{if(!(x)){fprintf(stderr,"DUR_CHECK line%d: %s\n",__LINE__,#x);return 1;}}while(0)
static DMedium medium,base,committed,saved,settled;
static int put(store *s,unsigned k,unsigned v){uint8_t key=(uint8_t)k,value=(uint8_t)v;return store_put(s,&key,1,&value,1);}
static int del(store *s,unsigned k){uint8_t key=(uint8_t)k;return store_delete(s,&key,1);}
static const int maps[3][16]={{-1,10,20,-1,-1,50,-1,-1,-1,90,-1,-1,-1,-1,-1,-1},{-1,11,-1,30,-1,55,-1,-1,-1,90,-1,-1,-1,-1,-1,-1},{-1,-1,-1,31,40,-1,-1,-1,-1,90,-1,-1,-1,-1,-1,-1}};
typedef struct {const int *map;unsigned pos,count;int bad;} Visit;
static int visit(void *ctx,const uint8_t *key,size_t n,const uint8_t *value,size_t z){Visit *v=ctx;while(v->pos<16&&v->map[v->pos]<0)v->pos++;if(v->pos>=16||n!=1||z!=1||key[0]!=v->pos||value[0]!=v->map[v->pos])v->bad=1;v->pos++;v->count++;return 0;}
static int equal(store *s,unsigned which){unsigned count=0;for(unsigned i=0;i<16;i++){uint8_t key=(uint8_t)i,value=0xa5;size_t n=777;int r=store_get(s,&key,1,&value,1,&n);if(maps[which][i]<0){if(r!=STORE_NOT_FOUND||value!=0xa5||n!=777)return 0;}else{count++;if(r!=STORE_OK||n!=1||value!=maps[which][i])return 0;}}Visit v={maps[which],0,0,0};return store_check(s)==STORE_OK&&store_scan(s,NULL,0,visit,&v)==STORE_OK&&!v.bad&&v.count==count;}
static int seed(void){dm_init(&medium);store s;CHECK(store_format(dm_io(&medium))==STORE_OK&&store_open(&s,dm_io(&medium))==STORE_OK&&store_begin(&s)==STORE_OK);for(unsigned i=0;i<16;i++)if(maps[0][i]>=0)CHECK(put(&s,i,(unsigned)maps[0][i])==STORE_OK);CHECK(store_commit(&s)==STORE_OK&&store_checkpoint(&s)==STORE_OK&&equal(&s,0));dm_reboot(&medium);base=medium;return 0;}
static int change(store *s,unsigned which){CHECK(store_begin(s)==STORE_OK);for(unsigned i=0;i<16;i++){if(maps[which][i]>=0)CHECK(put(s,i,(unsigned)maps[which][i])==STORE_OK);else{int r=del(s,i);CHECK(r==STORE_OK||r==STORE_NOT_FOUND);}}return 0;}
static int commit_cuts(int emit){CHECK(seed()==0);unsigned cases=0;for(unsigned mode=0;mode<=DM_MIDDLE;mode++)for(unsigned cut=1;cut<=37;cut++){medium=base;store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,cut,mode,0,0,0)==0);int result=store_commit(&s);CHECK(result==STORE_IO||result==STORE_INDETERMINATE||result==STORE_OK);if(result!=STORE_OK){CHECK(s.poisoned&&store_begin(&s)==STORE_STATE);}dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK);int old=equal(&s,0),next=equal(&s,1);CHECK(old||next);CHECK(result!=STORE_OK||next);CHECK(result!=STORE_IO||old);if(emit)printf("%u %u %d %d\n",mode,cut,result,next);cases++;}if(!emit)printf("DUR commit validated schedules=%u modes=7\n",cases);return 0;}
static int checkpoint_cuts(void){CHECK(seed()==0);medium=base;store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK);committed=medium;store source=s;unsigned cases=0;for(unsigned mode=0;mode<=DM_MIDDLE;mode++)for(unsigned cut=1;cut<=37;cut++){medium=committed;s=source;CHECK(dm_arm(&medium,cut,mode,0,0,0)==0);(void)store_checkpoint(&s);dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1));cases++;}printf("DUR checkpoint validated schedules=%u\n",cases);return 0;}
static int repeated(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK);dm_reboot(&medium);committed=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1));saved=medium;unsigned cases=0;for(unsigned first=1;first<=37;first++)for(unsigned second=1;second<=37;second++){medium=committed;CHECK(dm_arm(&medium,first,DM_EVEN,0,0,0)==0);(void)store_open(&s,dm_io(&medium));dm_reboot(&medium);CHECK(dm_arm(&medium,second,DM_MIDDLE,0,0,0)==0);(void)store_open(&s,dm_io(&medium));dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1)&&memcmp(medium.stable[2],saved.stable[2],32*4096)==0);settled=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1)&&medium.writes==settled.writes&&memcmp(medium.stable,settled.stable,sizeof medium.stable)==0);cases++;}printf("DUR repeated validated double-cuts=%u canonical-homes-and-whole-image-idempotent\n",cases);return 0;}
static int lies(void){CHECK(seed()==0);store s;medium=base;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,37,0,0)==0&&store_commit(&s)==STORE_OK);dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,0));medium=base;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,36,DM_SUBSET,35,0,UINT64_C(4))==0&&store_commit(&s)==STORE_INDETERMINATE);dm_reboot(&medium);saved=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_CORRUPT&&memcmp(medium.stable,saved.stable,sizeof medium.stable)==0);puts("DUR lies validated acknowledged-old-and-marker-without-batch");return 0;}
#ifndef DUR_ORIGINAL
#define DUR_ORIGINAL 0
#endif
static uint32_t crc(const uint8_t *p,size_t n){uint32_t c=UINT32_MAX;for(size_t i=0;i<n;i++){c^=p[i];for(unsigned j=0;j<8;j++)c=(c>>1)^(UINT32_C(0xedb88320)&(0u-(c&1u)));}return ~c;}
static void w32(uint8_t *p,uint32_t v){for(unsigned i=0;i<4;i++)p[i]=(uint8_t)(v>>(8*i));}
static void reseal(uint8_t *p){w32(p+4092,crc(p,4092));}
static void rebind(unsigned logical){uint8_t *p=medium.stable[34+logical];reseal(p);w32(medium.stable[66]+32+4*logical,crc(p,4092));reseal(medium.stable[66]);}
static int invalid(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK);dm_reboot(&medium);committed=medium;for(unsigned kind=0;kind<8;kind++){medium=committed;
 if(kind==0)medium.stable[65][100]^=1;
 if(kind==1){w32(medium.stable[34]+20,0);rebind(0);}
 if(kind==2){medium.stable[35][21]=8;rebind(1);}
 if(kind==3){w32(medium.stable[35]+24,1);rebind(1);}
 if(kind==4){w32(medium.stable[34]+24,UINT32_C(0x80000003));rebind(0);}
 if(kind==5){medium.stable[65][8]=3;rebind(31);}
 if(kind==6){w32(medium.stable[66]+16,31);reseal(medium.stable[66]);}
 if(kind==7){medium.stable[66][8]=3;reseal(medium.stable[66]);}
 saved=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_CORRUPT&&s.poisoned);
 if(DUR_ORIGINAL&&kind>=1&&kind<=4){CHECK(medium.writes>saved.writes&&memcmp(medium.stable,saved.stable,sizeof medium.stable)!=0);}
 else CHECK(medium.writes==saved.writes&&memcmp(medium.stable,saved.stable,sizeof medium.stable)==0);
 }
 if(!DUR_ORIGINAL)for(unsigned at=1;at<=37;at++){medium=committed;medium.read_cut=(unsigned)medium.reads+at;medium.short_read=1;saved=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_IO&&s.poisoned&&medium.writes==saved.writes&&memcmp(medium.stable,saved.stable,sizeof medium.stable)==0);}
 medium=committed;medium.stable[66][8]=0;reseal(medium.stable[66]);saved=medium;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,0)&&medium.writes==saved.writes);
 printf("DUR invalid validated structural-before-home=%d classes=8 stale-marker=1\n",!DUR_ORIGINAL);return 0;}
static int successive(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK);committed=medium;unsigned cases=0;for(unsigned mode=0;mode<=DM_MIDDLE;mode++)for(unsigned cut=1;cut<=37;cut++){medium=committed;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1)&&change(&s,2)==0&&dm_arm(&medium,cut,mode,0,0,0)==0);int r=store_commit(&s);dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK);int one=equal(&s,1),two=equal(&s,2);CHECK((one||two)&&!equal(&s,0));CHECK(r!=STORE_OK||two);CHECK(r!=STORE_IO||one);cases++;}printf("DUR successive validated schedules=%u acknowledged-prefix-retained\n",cases);return 0;}
static int medium_oracle(void){uint8_t a[4096],b[4096],out[4096];memset(a,17,4096);memset(b,34,4096);for(unsigned subset=0;subset<4;subset++){dm_init(&medium);uint64_t mask=(subset&1?UINT64_C(2):0)|(subset&2?UINT64_C(4):0);CHECK(dm_arm(&medium,3,DM_SUBSET,0,mask,0)==0&&dm_write(&medium,1,a)==0&&dm_write(&medium,2,b)==0&&dm_read(&medium,1,out)==0&&memcmp(out,a,4096)==0&&medium.stable[1][0]==0&&dm_flush(&medium)==1);dm_reboot(&medium);printf("S %u %u %u\n",subset,medium.stable[1][0],medium.stable[2][4095]);}
 for(unsigned mode=0;mode<8;mode++){dm_init(&medium);CHECK(dm_arm(&medium,1,mode,0,UINT64_C(4),0)==0&&dm_write(&medium,2,b)==1);dm_reboot(&medium);printf("T %u",mode);unsigned positions[]={0,511,512,1023,1024,2047,2048,4091,4095};for(unsigned i=0;i<9;i++)printf(" %u",medium.stable[2][positions[i]]);putchar('\n');}return 0;}
static int decode_oracle(void){uint8_t bytes[4096];unsigned v;while(scanf("%2x",&v)==1){bytes[0]=(uint8_t)v;for(unsigned i=1;i<4096;i++){CHECK(scanf("%2x",&v)==1);bytes[i]=(uint8_t)v;}store_node node;int r=store_page_decode(1,7,bytes,&node);printf("%d %u\n",r,r?0u:node.value[0][0]);}return 0;}
static int trace(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK);for(unsigned i=0;i<medium.event;i++)printf("C %u %u\n",medium.trace[i].kind,medium.trace[i].page);CHECK(dm_arm(&medium,0,0,0,0,0)==0&&store_checkpoint(&s)==STORE_OK);for(unsigned i=0;i<medium.event;i++)printf("R %u %u\n",medium.trace[i].kind,medium.trace[i].page);return 0;}
static int metadata_slots(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK);for(unsigned gen=2;gen<=5;gen++){CHECK(change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0&&store_commit(&s)==STORE_OK&&dm_arm(&medium,0,0,0,0,0)==0&&store_checkpoint(&s)==STORE_OK);CHECK(medium.trace[33].kind==1&&medium.trace[33].page==(gen&1u));CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&s.generation==gen&&equal(&s,1));}dm_init(&medium);CHECK(store_format(dm_io(&medium))==STORE_OK);for(unsigned p=2;p<34;p++){memset(medium.stable[p]+8,0xff,8);reseal(medium.stable[p]);}memset(medium.stable[1]+8,0xff,8);reseal(medium.stable[1]);CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&s.generation==UINT64_MAX&&store_begin(&s)==STORE_OK&&put(&s,1,9)==STORE_OK);uint64_t writes=medium.writes;CHECK(store_commit(&s)==STORE_FULL&&!s.active&&!s.poisoned&&medium.writes==writes);puts("DUR metadata validated alternating-and-no-wrap");return 0;}
typedef struct {DMedium *medium;pthread_mutex_t lock;pthread_cond_t cv;int held,release,result;store *engine;} AckGate;
static int ack_read(void *p,uint32_t id,void *b){return dm_read(((AckGate *)p)->medium,id,b);}
static int ack_write(void *p,uint32_t id,const void *b){return dm_write(((AckGate *)p)->medium,id,b);}
static int ack_flush(void *p){AckGate *g=p;int r=dm_flush(g->medium);if(r||g->medium->event!=37)return r;if(pthread_mutex_lock(&g->lock))return 1;g->held=1;(void)pthread_cond_broadcast(&g->cv);while(!g->release)(void)pthread_cond_wait(&g->cv,&g->lock);(void)pthread_mutex_unlock(&g->lock);return 1;}
static void *ack_worker(void *p){AckGate *g=p;g->result=store_commit(g->engine);return NULL;}
static int late_ack(void){CHECK(seed()==0);store s;CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&change(&s,1)==0&&dm_arm(&medium,0,0,0,0,0)==0);AckGate g={0};g.medium=&medium;g.engine=&s;g.result=-99;CHECK(pthread_mutex_init(&g.lock,NULL)==0&&pthread_cond_init(&g.cv,NULL)==0);s.io=(store_io){&g,ack_read,ack_write,ack_flush,67};pthread_t thread;CHECK(pthread_create(&thread,NULL,ack_worker,&g)==0&&pthread_mutex_lock(&g.lock)==0);while(!g.held)CHECK(pthread_cond_wait(&g.cv,&g.lock)==0);CHECK(g.result==-99&&medium.stable[66][8]==2&&!medium.dirty[66]);g.release=1;CHECK(pthread_cond_broadcast(&g.cv)==0&&pthread_mutex_unlock(&g.lock)==0&&pthread_join(thread,NULL)==0);CHECK(g.result==STORE_INDETERMINATE&&s.poisoned&&store_begin(&s)==STORE_STATE);CHECK(pthread_cond_destroy(&g.cv)==0&&pthread_mutex_destroy(&g.lock)==0);dm_reboot(&medium);CHECK(store_open(&s,dm_io(&medium))==STORE_OK&&equal(&s,1));puts("DUR late_ack validated retained-until-join-then-reconcile-new");return 0;}
int main(int argc,char **argv){if(argc!=2)return 2;if(!strcmp(argv[1],"commit"))return commit_cuts(0);if(!strcmp(argv[1],"oracle"))return commit_cuts(1);if(!strcmp(argv[1],"checkpoint"))return checkpoint_cuts();if(!strcmp(argv[1],"repeated"))return repeated();if(!strcmp(argv[1],"lies"))return lies();if(!strcmp(argv[1],"invalid"))return invalid();if(!strcmp(argv[1],"successive"))return successive();if(!strcmp(argv[1],"medium"))return medium_oracle();if(!strcmp(argv[1],"decode"))return decode_oracle();if(!strcmp(argv[1],"trace"))return trace();if(!strcmp(argv[1],"metadata"))return metadata_slots();if(!strcmp(argv[1],"late_ack"))return late_ack();return 2;}
